import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div"> {}

<const/{ class: className, content, ...rest }=input/>

<div data-slot="alert-action" class=cn("mu-alert-action", className) ...rest>
  <${content}/>
</div>

import { alertVariants, type AlertVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div">, AlertVariants {}

<const/{ variant, class: className, content, ...rest }=input/>

<div data-slot="alert" role="alert" class=cn(alertVariants({ variant }), className) ...rest>
  <${content}/>
</div>

